func mergeStructs(s1, s2 *structpb.Struct) *structpb.Struct {
	if s1 == nil {
		return s2
	}
	if s2 == nil {
		return s1
	}
	merged := s1.AsMap()
	maps.Copy(merged, s2.AsMap())
	result, _ := structpb.NewStruct(merged)
