func defaultSupportedManagementPolicies() []sets.Set[xpv2.ManagementAction] {
	return []sets.Set[xpv2.ManagementAction]{
		// Default (all), the standard behaviour of crossplane in which all
		// reconciler actions are done.
		sets.New[xpv2.ManagementAction](xpv2.ManagementActionAll),
		// All actions explicitly set, the same as default.
		sets.New[xpv2.ManagementAction](xpv2.ManagementActionObserve, xpv2.ManagementActionCreate, xpv2.ManagementActionUpdate, xpv2.ManagementActionLateInitialize, xpv2.ManagementActionDelete),
		// ObserveOnly, just observe action is done, the external resource is
		// considered as read-only.
		sets.New[xpv2.ManagementAction](xpv2.ManagementActionObserve),
		// Pause, no action is being done. Alternative to setting the pause
		// annotation.
		sets.New[xpv2.ManagementAction](),
		// No LateInitialize filling in the spec.forProvider, allowing some
		// external resource fields to be managed externally.
		sets.New[xpv2.ManagementAction](xpv2.ManagementActionObserve, xpv2.ManagementActionCreate, xpv2.ManagementActionUpdate, xpv2.ManagementActionDelete),
		// No Delete, the external resource is not deleted when the managed
		// resource is deleted.
		sets.New[xpv2.ManagementAction](xpv2.ManagementActionObserve, xpv2.ManagementActionCreate, xpv2.ManagementActionUpdate, xpv2.ManagementActionLateInitialize),
		// No Delete and no LateInitialize, the external resource is not deleted
		// when the managed resource is deleted and the spec.forProvider is not
		// late initialized.
		sets.New[xpv2.ManagementAction](xpv2.ManagementActionObserve, xpv2.ManagementActionCreate, xpv2.ManagementActionUpdate),
		// No Update, the external resource is not updated when the managed
		// resource is updated. Useful for immutable external resources.
		sets.New[xpv2.ManagementAction](xpv2.ManagementActionObserve, xpv2.ManagementActionCreate, xpv2.ManagementActionDelete, xpv2.ManagementActionLateInitialize),
		// No Update and no Delete, the external resource is not updated
		// when the managed resource is updated and the external resource
		// is not deleted when the managed resource is deleted.
		sets.New[xpv2.ManagementAction](xpv2.ManagementActionObserve, xpv2.ManagementActionCreate, xpv2.ManagementActionLateInitialize),
		// No Update and no LateInitialize, the external resource is not updated
		// when the managed resource is updated and the spec.forProvider is not
		// late initialized.
		sets.New[xpv2.ManagementAction](xpv2.ManagementActionObserve, xpv2.ManagementActionCreate, xpv2.ManagementActionDelete),
		// No Update, no Delete and no LateInitialize, the external resource is
		// not updated when the managed resource is updated, the external resource
		// is not deleted when the managed resource is deleted and the
		// spec.forProvider is not late initialized.
		sets.New[xpv2.ManagementAction](xpv2.ManagementActionObserve, xpv2.ManagementActionCreate),
		// Like ObserveOnly, but the external resource is deleted when the
		// managed resource is deleted.
		sets.New[xpv2.ManagementAction](xpv2.ManagementActionObserve, xpv2.ManagementActionDelete),
		// No Crate and no Delete. Just update/patch the external resource.
		// Useful when the same external resource is managed by multiple
		// managed resources.
		sets.New[xpv2.ManagementAction](xpv2.ManagementActionObserve, xpv2.ManagementActionUpdate),
		// Import mode: Allows observation of existing resources and populates spec.forProvider
		// through late initialization, without making any changes to the external resource.
		// Useful for safely importing existing resources to discover their current state.
		sets.New[xpv2.ManagementAction](xpv2.ManagementActionObserve, xpv2.ManagementActionLateInitialize),
		// No Create, no Delete. Just Observe, Update and LateInitialize.
		// Useful when external resource lifecycle is managed elsewhere but you want
		// to allow Crossplane to make updates and discover state changes.
		sets.New[xpv2.ManagementAction](xpv2.ManagementActionObserve, xpv2.ManagementActionUpdate, xpv2.ManagementActionLateInitialize),
	}
}

